185		std::string fixPlaceholders(const std::string& clause)
186		{
187			auto pSPP = _pContext->statementPlaceholderProvider();
188	
189			std::string result;
190			auto it = clause.begin();
191			auto end = clause.end();
192			while (it != end)
193			{
194				switch (*it)
195				{
196				case '"':
197					result += *it++;
198					while (it != end && *it != '"') result += *it++;
199					if (it != end) result += *it++;
200					break;
201	
202				case '\'':
203					result += *it++;
204					while (it != end && *it != '\'') result += *it++;
205					if (it != end) result += *it++;
206					break;
207	
208				case '?':
209					result += pSPP->next();
210					++it;
211					break;
212	
213				default:
214					result += *it++;
215					break;
216				}
217			}
218			return result;
219		}
