98	Var Query::find(const std::string& path) const
99	{
100		Var result = _source;
101		if (path.empty()) return result;
102		bool found = false;
103		StringTokenizer tokenizer(path, ".");
104		for (const auto& token: tokenizer)
105		{
106			if (!result.isEmpty())
107			{
108				std::vector<int> indexes;
109				RegularExpression::MatchVec matches;
110				int firstOffset = -1;
111				int offset = 0;
112				RegularExpression regex("\\[([0-9]+)\\]");
113				while (regex.match(token, offset, matches) > 0)
114				{
115					if (firstOffset == -1)
116					{
117						firstOffset = static_cast<int>(matches[0].offset);
118					}
119					std::string num(token, matches[1].offset, matches[1].length);
120					indexes.push_back(NumberParser::parse(num));
121					offset = static_cast<int>(matches[0].offset + matches[0].length);
122				}
123	
124				std::string name(token);
125				if (firstOffset != -1)
126				{
127					name = name.substr(0, firstOffset);
128				}
129	
130				if (name.length() > 0)
131				{
132					if (result.type() == typeid(Object::Ptr))
133					{
134						Object::Ptr o = result.extract<Object::Ptr>();
135						result = o->get(name);
136						found = true;
137					}
138					else if (result.type() == typeid(Object))
139					{
140						Object o = result.extract<Object>();
141						result = o.get(name);
142						found = true;
143					}
144					else result.clear();
145	
146				}
147	
148				if (!result.isEmpty() && !indexes.empty())
149				{
150					for (const auto& i: indexes)
151					{
152						if (result.type() == typeid(Array::Ptr))
153						{
154							Array::Ptr array = result.extract<Array::Ptr>();
155							result = array->get(i);
156							if (result.isEmpty()) break;
157						}
158						else if (result.type() == typeid(Array))
159						{
160							Array array = result.extract<Array>();
161							result = array.get(i);
162							if (result.isEmpty()) break;
163						}
164					}
165				}
166			}
167		}
168		if (!found) result.clear();
169		return result;
170	}
